/**
 * Every Tailwind class a CMS block can emit, as LITERAL strings in maps.
 *
 * Why one file: published CMS pages are HTML stored in the database, rendered
 * months before the CSS that styles them is rebuilt. A class that only exists in
 * a template string (`text-${color}`) is never generated by Tailwind, and the
 * page silently loses its styling. Blocks therefore pick classes ONLY from the
 * maps below, and `CMS_CLASS_LIST` (every class in every map) is checked against
 * the built public CSS by scripts/check-cms-classes.mjs. The visual language
 * mirrors the existing pages (WhyUsPage, ContactPage, ProductsPage, FAQ,
 * Testimonials, Ingredients): olive-dark headings in Playfair, light brown body
 * copy, gold kickers, cream cards with the soft olive shadow.
 */
import type { Align, ButtonStyle, HeadingLevel, Pad, SectionBg, TextColor } from '../contracts';

export type Tone = 'light' | 'dark';

